function xhSvg(x,w){var s=3+x.size*3,g=Math.max(.8,1+x.gap*1.5),t=Math.max(1.2,x.thick*1.3),c=60,R=[];
 R.push('<rect class="a ar" x="'+(c+g)+'" y="'+(c-t/2)+'" width="'+s+'" height="'+t+'"/>');
 R.push('<rect class="a al" x="'+(c-g-s)+'" y="'+(c-t/2)+'" width="'+s+'" height="'+t+'"/>');
 R.push('<rect class="a ad2" x="'+(c-t/2)+'" y="'+(c+g)+'" width="'+t+'" height="'+s+'"/>');
 R.push('<rect class="a au" x="'+(c-t/2)+'" y="'+(c-g-s)+'" width="'+t+'" height="'+s+'"/>');
 if(x.dot)R.push('<rect x="'+(c-t/2)+'" y="'+(c-t/2)+'" width="'+t+'" height="'+t+'"/>');
 if(x.only){var q=Math.max(2.4,t*1.4);R=['<rect x="'+(c-q/2)+'" y="'+(c-q/2)+'" width="'+q+'" height="'+q+'"/>']}
 return '<svg width="'+w+'" height="'+w+'" viewBox="0 0 120 120" aria-hidden="true" style="overflow:visible"><g fill="'+x.hex+'" stroke="#000" stroke-width="'+(x.outline?1:.35)+'">'+R.join("")+'</g></svg>'}
