var B57="ABCDEFGHJKLMNOPQRSTUVWXYZabcdefhijkmnopqrstuvwxyz23456789";
function b57dec(s,nbytes){var n=0n;for(var i=s.length-1;i>=0;i--){var k=B57.indexOf(s[i]);if(k<0)return null;n=n*57n+BigInt(k)}
 var b=new Array(nbytes);for(var j=nbytes-1;j>=0;j--){b[j]=Number(n&255n);n>>=8n}return n===0n?b:null}
function b57enc(b,len){var n=0n;b.forEach(function(x){n=(n<<8n)+BigInt(x)});var o="";for(var i=0;i<len;i++){o+=B57[Number(n%57n)];n/=57n}return o}
var TPL=b57dec("CSdpH9aUv4mNAWc2hfAOdTrJ8J6H6HUFuvWxYMZXshvmPG".slice(2),32);
function s8(v){return v>127?v-256:v}
function oldDecode(code){var s=(code||"").trim().replace(/^CSGO-?/i,"").replace(/-/g,"");if(s.length!==25)return null;var b=b57dec(s,18);if(!b)return null;
 var sum=0;for(var i=1;i<18;i++)sum+=b[i];if(sum%256!==b[0])return null;
 return {gap:s8(b[2])/10,outline:b[3]/2,rgb:[b[4],b[5],b[6]],alpha:b[7],thick:b[12]/10,style:(b[13]&15)>>1,dot:(b[13]>>4)&1,alphaOn:(b[13]>>6)&1,t:(b[13]>>7)&1,size:(b[14]|((b[15]&31)<<8))/10,color:b[10]&7,outl:(b[10]>>3)&1}}
function newDecode(code){var s=(code||"").trim();if(!/^CS[A-Za-z0-9]{44}$/.test(s)||/^CSGO/i.test(s))return null;var b=b57dec(s.slice(2),32);if(!b)return null;var sum=0;for(var i=1;i<32;i++)sum+=b[i];if(sum%256!==b[0])return null;
 return {h:b[2]|(b[3]<<8),style:b[4]&31,dot:(b[4]>>6)&1,t:(b[4]>>7)&1,rgb:[b[5],b[6],b[7]],alpha:b[8],thick:b[13]&63,outline:b[13]>>6?1:0,gap:s8(b[14]),length:b[16]}}
var PRESET={0:[250,50,50],1:[50,250,50],2:[250,250,50],3:[50,50,250],4:[50,250,250]};
function convertOld(o,H){var rgb=o.color===5?o.rgb:(PRESET[o.color]||o.rgb);
 return {h:H,style:4,dyn:[0,2,3,5].indexOf(o.style)>-1,dot:o.dot,t:o.t,rgb:rgb,alpha:o.alphaOn?o.alpha:255,
  thick:Math.max(1,Math.round(o.thick*H/480)),length:Math.max(0,Math.round(o.size*H/480)),gap:Math.max(0,Math.round(o.gap+5)),outline:o.outl?1:0}}
function newEncode(c){var b=TPL.slice();b[2]=c.h&255;b[3]=(c.h>>8)&255;b[4]=(c.style&31)|(c.dot<<6)|(c.t<<7);b[5]=c.rgb[0];b[6]=c.rgb[1];b[7]=c.rgb[2];b[8]=c.alpha;
 b[13]=(c.thick&63)|(c.outline<<6);var g=c.gap&65535;b[14]=g&255;b[15]=(g>>8)&255;b[16]=c.length&255;var sum=0;for(var i=1;i<32;i++)sum+=b[i];b[0]=sum%256;return "CS"+b57enc(b,44)}
function cname(rgb){var r=rgb[0],g=rgb[1],b=rgb[2];if(r>200&&g>200&&b>200)return "Белый";if(r>200&&g>200&&b<120)return "Жёлтый";if(g>180&&b>180&&r<170)return "Голубой";if(g>180&&r<140&&b<200)return "Зелёный";return "Свой цвет"}
